import java.io.*;

public class Demo {
    static int parseMark(String text) {
        int mark = Integer.parseInt(text.trim());
        if (mark < 0 || mark > 100) throw new IllegalArgumentException("out of range: " + mark);
        return mark;
    }

    static int total(BufferedReader in) throws IOException {
        int sum = 0;
        String line;
        while ((line = in.readLine()) != null) {
            System.out.println("  total() read " + line);
            sum += parseMark(line);
        }
        System.out.println("  total() finished");
        return sum;
    }

    public static void main(String[] args) {
        String[] inputs = {"70\n25", "70\n250\n5", "70\nabc"};
        for (String text : inputs) {
            try (BufferedReader in = new BufferedReader(new StringReader(text))) {
                System.out.println("sum = " + total(in));
            } catch (IllegalArgumentException e) {
                System.out.println("main caught " + e.getClass().getSimpleName() + ": " + e.getMessage());
            } catch (IOException e) {
                System.out.println("could not read the input");
            }
        }
    }
}

